"""Authored synthetic arithmetic example, not a real study or a source-paper parser."""
import csv,json
from pathlib import Path
root=Path(__file__).resolve().parent

def write(name,value):
    (root/name).write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
records=[
('Abstract','This authored demonstration contains 200 synthetic reports. It illustrates why higher error detection does not necessarily mean better overall review. No patients, readers, or trained models were studied.','本自编演示包含 200 份合成报告，用来说明更高的错误检出率不一定意味着更好的总体审阅效果。本演示未研究患者、阅片者或受训模型。','主张与范围','界定这是教学构造，结论只涉及给定算术例子。','不能将这些数字当作真实模型的临床证据。','higher error detection','claim'),
('Methods','The synthetic dataset has 40 reports with errors and 160 reports without errors. The two conditions are constructed rules applied to the same reports, rather than independent human reading experiments.','合成数据集包含 40 份有错误报告和 160 份无错误报告。两个条件是在同一批报告上应用的构造规则，而不是独立的人工阅片实验。','方法','明确两组结果共享同一数据及已知标签。','同一病例构造比较不证明规则在新材料上的泛化能力。','40 reports with errors','method'),
('Results','Rule A flags 26 of the 40 error reports and 8 of the 160 correct reports. Rule B flags 35 of the 40 error reports and 15 of the 160 correct reports.','规则 A 标记 40 份错误报告中的 26 份，以及 160 份正确报告中的 8 份。规则 B 标记 40 份错误报告中的 35 份，以及 160 份正确报告中的 15 份。','证据','提供表格和图形的原始计数，区分真正例和假警报。','规则 B 提高检出数量，也增加对正确报告的误报。','35 of the 40 error reports','evidence'),
('Results','Recall rises from 0.65 to 0.875, but the false-alert proportion also rises from 0.05 to 0.09375. The denominator for recall is 40, whereas the denominator for false alerts is 160.','召回率从 0.65 升至 0.875，但假警报比例也从 0.05 升至 0.09375。召回率的分母是 40，而假警报比例的分母是 160。','指标比较','用两个不同分母解释同一规则改变的收益与代价。','不要把假警报比例的分母换成全部 200 份报告，或把召回率升高概括为所有指标均改善。','The denominator for recall is 40','concept'),
('Discussion','A reviewer who only sees recall may prefer Rule B. That preference depends on the costs of missed errors and unnecessary alerts. These costs were not measured, so the demonstration does not establish which rule is more useful.','只看到召回率的审阅者可能更偏好规则 B。该偏好取决于漏检错误和不必要警报的代价。本演示没有测量这些代价，因此不能确定哪条规则更有用。','局限','将指标变化与实际效用分开，避免把算术例子提升为部署结论。','真实应用需要额外的效用和工作流程研究。','These costs were not measured','limitation'),
('Conclusion','The transferable lesson is to report both benefits and errors with their denominators. All counts can be regenerated from the accompanying CSV. The example is complete as an authored teaching fixture, not as evidence about a medical system.','可迁移的做法是同时报告收益、错误及各自分母。所有计数均可由随附 CSV 重建。该示例是完整的自编教学样例，不是医疗系统的实证证据。','结论','总结本例能支持的阅读方法，并提供可复算数据。','不对真实论文的模型效果作出推断。','report both benefits and errors with their denominators','claim')]
units=[]
for i,(section,en,zh,role,logic,crit,quote,kind) in enumerate(records,1):
    units.append({'id':f'P{i:03}','section':section,'unit_type':'abstract' if i==1 else 'body','original_text':en,'translation_zh':zh,'rhetorical_function':{'primary':role,'secondary':[]},'logical_role':logic,'critical_commentary':crit,'depth':'deep' if i in (3,4) else 'brief','status':{'translation':'done','annotation':'deep' if i in (3,4) else 'brief','extraction':'verified','source_check':'sampled'},'highlights':[{'quote':quote,'category':kind}]})
write('units.json',units)
write('paper.json',{'title':'Error Detection and False Alerts: A Synthetic Reading Example','authors':'Academic Paper Annotator contributors · 自编合成教学材料','notice':'所有材料和数据均为自编合成示例，不是真实研究。浏览器呈现未在本环境验证；静态与脚本逻辑检查另列。','guide':'对照两条规则的检出与误报，重点核对不同指标的分母。','source_note':'来源为本目录 source.md 和 reports.csv。无患者数据，无第三方论文全文，无外部附件。中文和批注为配套自编说明。','references':[]})
write('figures.json',[{'id':'F001','original_text':'Recall and false-alert proportions for the two synthetic rules.','translation_zh':'两条合成规则的召回率和假警报比例。','image_path':'proportions.svg'}])
write('tables.json',[{'id':'T001','title':'Synthetic rule outcomes / 合成规则结果','caption':'Counts from the authored CSV / 自编 CSV 计数','rows':[['Condition','Flagged error reports','Flagged correct reports'],['Rule A','26','8'],['Rule B','35','15']],'label_translations':{'Condition':'条件','Flagged error reports':'标记的错误报告','Flagged correct reports':'标记的正确报告','Rule A':'规则 A','Rule B':'规则 B'}}])
write('baseline.json',{'required_unit_ids':[u['id'] for u in units],'unit_counts':{'abstract':1,'body':5},'figure_count':1,'table_count':1,'reference_ids':[],'baseline_method':'Authored source.md has six named paragraphs; CSV explicitly defines 40 error and 160 correct reports. One source-authored figure and one three-row table are supplied.'})
write('analysis.json',{'claims':[{'id':'C001','claim':'规则 B 的召回率更高，但误报比例也更高。','quote':'Recall rises from 0.65 to 0.875','units':['P004'],'scope':'仅限给定的合成规则与样本；不代表真实人机实验。'},{'id':'C002','claim':'现有例子不能确定哪条规则更有用。','quote':'the demonstration does not establish which rule is more useful','units':['P005'],'scope':'缺少漏检与误报代价，不能从单项指标推出净收益。'}],'relations':[{'from':'P003','to':'P004','relation':'计数支持比率'},{'from':'P004','to':'C001','relation':'支持'},{'from':'P005','to':'C002','relation':'限定'},{'from':'C001','to':'C002','relation':'不等于效用判断'}],'graph_labels':{'P003':'原始计数','P004':'指标与分母','C001':'收益与代价并存','P005':'缺少代价测量','C002':'效用仍不确定'},'section_reviews':{'Abstract':'先界定合成材料的性质；不把教学例子当实证研究。','Methods':'两个条件共享样本，不能误称独立阅片实验。','Results':'检出和误报变化都有明确分母。','Discussion':'指标不等于临床或业务效用。','Conclusion':'把计数、指标、限制和可复算数据一起交付。'},'evaluation':['较强部分是全部计数可以由 CSV 直接复算。','主要限制是数据和规则均由作者构造，不能估计真实泛化性能。'],'learning':['先报告计数，再给出比率。','保持不同指标的分母清晰。','将作者表述和分析者评价分开。'],'questions':['在真实且独立的样本上，两个规则的收益与代价会如何变化？']})
(root/'source.md').write_text('# Authored synthetic source — not a real study\n\n'+'\n\n'.join(f'## P{i:03} — {r[0]}\n{r[1]}' for i,r in enumerate(records,1))+'\n',encoding='utf-8')
with (root/'reports.csv').open('w',newline='',encoding='utf-8') as f:
    writer=csv.writer(f,lineterminator='\n');writer.writerow(['report_id','has_error','rule_a_flag','rule_b_flag'])
    for i in range(1,201):writer.writerow([f'S{i:03}',int(i<=40),int(i<=26 or 41<=i<=48),int(i<=35 or 41<=i<=55)])
